<?php /** @var \Illuminate\Database\Eloquent\Collection $products */ /** @var \Illuminate\Database\Eloquent\Collection $businesses */ /** @var ?\App\Models\ExchangeRate $customRate */ ?>
<style>.disabled-product-action,.price-reference{position:relative;display:inline-flex}.disabled-product-action:hover:after,.price-reference:hover:after,.price-reference:focus:after{position:absolute;z-index:10;bottom:calc(100% + 8px);left:50%;width:max-content;max-width:220px;padding:8px 10px;border-radius:8px;background:#182230;color:#fff;font-size:11px;font-weight:600;line-height:1.35;text-align:center;box-shadow:var(--shadow);transform:translateX(-50%)}.disabled-product-action:hover:after{content:'No se puede eliminar un producto con registros asociados'}.price-reference{cursor:help;border-bottom:1px dashed #98a2b3}.price-reference:hover:after,.price-reference:focus:after{content:attr(data-tooltip)}.price-reference:focus{outline:2px solid #635bff;border-radius:3px;outline-offset:3px}.data-table .product-category,.data-table .product-price,.data-table .stock-total{text-align:center}</style>
<header class="page-head"><div><span class="eyebrow">INVENTARIO</span><h1>Productos</h1><p>Precios y existencias por local.</p></div><button class="btn btn-primary" onclick="document.querySelector('#new').showModal()">+ Añadir producto</button></header>
<div class="grid grid-3" style="max-width:820px;margin:0 0 20px"><div class="field"><label for="product-search">Buscar productos</label><input id="product-search" type="search" placeholder="Nombre del producto"></div><div class="field"><label for="product-category-filter">Categoría</label><select id="product-category-filter"><option value="">Todas las categorías</option><option value="phone">Teléfonos</option><option value="accessory">Accesorios</option><option value="spare_part">Repuestos</option></select></div><div class="field"><label for="product-stock-filter">Disponibilidad</label><select id="product-stock-filter"><option value="">Todo el inventario</option><option value="low-stock">Casi agotados</option><option value="out-of-stock">Agotados</option></select></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const search=document.querySelector('#product-search'),category=document.querySelector('#product-category-filter'),stock=document.querySelector('#product-stock-filter'),applyFilters=()=>document.querySelectorAll('.data-table tbody tr').forEach(row=>{const matchesSearch=row.querySelector('strong').textContent.toLowerCase().replace(/\s+/g,'').includes(search.value.toLowerCase().replace(/\s+/g,'')),matchesCategory=!category.value||row.dataset.category===category.value,matchesStock=!stock.value||(stock.value==='low-stock'?Number(row.dataset.stock)===1:Number(row.dataset.stock)===0);row.hidden=!(matchesSearch&&matchesCategory&&matchesStock)});[search,category,stock].forEach(filter=>filter.addEventListener('input',applyFilters))})</script>
<dialog class="card" id="new" style="border:0;padding:0;width:min(760px,90vw)"><form class="panel stack" method="post" action="./productos"><h2>Añadir producto</h2><div class="grid grid-3"><div class="field"><label>Nombre</label><input name="name" required placeholder="Nombre del producto"></div><div class="field"><label>Categoría</label><select name="category" required><option value="phone">Teléfono</option><option value="accessory">Accesorio</option><option value="spare_part">Repuesto</option></select></div><div class="field"><label>Precio USD</label><input name="price" type="number" min=".01" step=".01" required placeholder="0.00"></div></div><div class="grid grid-3"><?php foreach($businesses as $businessItem): ?><div class="field"><label>Stock · <?= htmlspecialchars($businessItem->name) ?></label><input name="stocks[<?= $businessItem->id ?>]" type="number" min="0" required value="0"></div><?php endforeach ?></div><div class="actions"><button class="btn btn-primary">Guardar producto</button><button type="button" class="btn btn-secondary" onclick="this.closest('dialog').close()">Cancelar</button></div></form></dialog>
<section class="card table-wrap"><div class="toolbar"><h2><?= $products->count() ?> productos</h2></div><table class="data-table"><thead><tr><th>Imagen</th><th>Producto</th><th class="product-category">Categoría</th><th class="product-price">Precio</th><th class="stock-total">Stock total</th><th></th></tr></thead><tbody><?php foreach($products as $product): $stock=$product->getStock(); $hasAssociatedRecords=$product->items_count+$product->layaways_count>0; $priceVes=$customRate ? $product->price*(float)$customRate->rate : null; ?><tr data-category="<?= $product->category ?>" data-stock="<?= $stock ?>"><td><img src="./resources/views/assets/product-placeholder.svg" alt="" width="44" height="44" style="display:block;border:1px solid #e0e7ff;border-radius:10px;background:#eef2ff"></td><td><strong><?= htmlspecialchars($product->name) ?></strong></td><td class="product-category"><?= ['phone'=>'Teléfono','accessory'=>'Accesorio','spare_part'=>'Repuesto'][$product->category] ?></td><td class="product-price"><?php if($priceVes !== null): ?><span class="price-reference" tabindex="0" data-tooltip="Bs. <?= number_format($priceVes,2,',','.') ?>">$<?= number_format($product->price,2,',','.') ?></span><?php else: ?>$<?= number_format($product->price,2,',','.') ?><?php endif ?></td><td class="stock-total"><?php if($stock === 0): ?>0 unidades<br><span class="status status-danger">Agotado</span><?php elseif($stock === 1): ?>1 unidad<br><span class="status status-warning">Casi agotado</span><?php else: ?><?= $stock ?> unidades<?php endif ?></td><td class="actions"><button class="btn btn-secondary btn-sm" onclick="document.querySelector('#edit-<?= $product->id ?>').showModal()">Editar</button><?php if($hasAssociatedRecords): ?><span class="disabled-product-action"><button class="btn btn-danger btn-sm" type="button" disabled style="cursor:not-allowed;opacity:.45;filter:grayscale(1)">Eliminar</button></span><?php else: ?><a class="btn btn-danger btn-sm" href="./productos/<?= $product->id ?>/eliminar">Eliminar</a><?php endif ?></td></tr><?php endforeach ?></tbody></table></section>
<?php foreach($products as $product): ?><dialog id="edit-<?= $product->id ?>" class="card" style="border:0;padding:0;width:min(700px,90vw)"><form method="post" action="./productos/<?= $product->id ?>" class="panel stack"><h2>Editar producto</h2><div class="grid grid-3"><div class="field"><label>Nombre</label><input name="name" value="<?= htmlspecialchars($product->name) ?>" required></div><div class="field"><label>Categoría</label><select name="category"><option value="phone" <?= $product->category==='phone'?'selected':'' ?>>Teléfono</option><option value="accessory" <?= $product->category==='accessory'?'selected':'' ?>>Accesorio</option><option value="spare_part" <?= $product->category==='spare_part'?'selected':'' ?>>Repuesto</option></select></div><div class="field"><label>Precio USD</label><input name="price" type="number" min=".01" step=".01" value="<?= number_format($product->price,2,'.','') ?>" required></div></div><div class="grid grid-3"><?php foreach($businesses as $businessItem): $batch=$product->batches->first(fn($b)=>$b->business_id===$businessItem->id); ?><div class="field"><label>Stock · <?= htmlspecialchars($businessItem->name) ?></label><input name="stocks[<?= $businessItem->id ?>]" type="number" min="0" value="<?= $batch?->stock ?? 0 ?>" required></div><?php endforeach ?></div><div class="actions"><button class="btn btn-primary">Guardar</button><button type="button" class="btn btn-secondary" onclick="this.closest('dialog').close()">Cancelar</button></div></form></dialog><?php endforeach ?>
